//! MAC vendor lookup against a bundled snapshot of the IEEE Registration
//! Authority's MAC address block registries (MA-L / MA-M / MA-S).
//!
//! The data comes straight from IEEE (`standards-oui.ieee.org`: `oui/oui.csv`,
//! `oui28/mam.csv`, `oui36/oui36.csv`), keeping only each assignment prefix and
//! its organization name. It is regenerated by `ci/gen-oui.py`, which also
//! records the retrieval date and source checksums in `data/oui/SNAPSHOT`.
//!
//! Layout (all big-endian, each table sorted by prefix for binary search):
//! `mal.bin` = `[u24 prefix][u24 name offset]`, `mam.bin` = `[u32 prefix (28
//! bits)][u24 offset]`, `mas.bin` = `[u40 prefix (36 bits)][u24 offset]`, and
//! `names.bin` = `[u8 len][UTF-8]…` deduplicated organization names. No
//! decompression, no allocation, no runtime I/O.

use crate::mac::Mac;

static MAL: &[u8] = include_bytes!("../data/oui/mal.bin");
static MAM: &[u8] = include_bytes!("../data/oui/mam.bin");
static MAS: &[u8] = include_bytes!("../data/oui/mas.bin");
static NAMES: &[u8] = include_bytes!("../data/oui/names.bin");
static SNAPSHOT: &str = include_str!("../data/oui/SNAPSHOT");

/// IEEE assignment block size.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Block {
    /// MA-L — 24-bit prefix (the classic "OUI").
    MaL,
    /// MA-M — 28-bit prefix.
    MaM,
    /// MA-S — 36-bit prefix.
    MaS,
}

impl Block {
    /// The IEEE registry name: `"MA-L"`, `"MA-M"`, or `"MA-S"`.
    pub fn as_str(self) -> &'static str {
        match self {
            Block::MaL => "MA-L",
            Block::MaM => "MA-M",
            Block::MaS => "MA-S",
        }
    }

    /// Prefix length in bits (24, 28, 36).
    pub fn prefix_bits(self) -> u32 {
        match self {
            Block::MaL => 24,
            Block::MaM => 28,
            Block::MaS => 36,
        }
    }

    fn key_len(self) -> usize {
        match self {
            Block::MaL => 3,
            Block::MaM => 4,
            Block::MaS => 5,
        }
    }

    fn table(self) -> &'static [u8] {
        match self {
            Block::MaL => MAL,
            Block::MaM => MAM,
            Block::MaS => MAS,
        }
    }
}

/// One registry match for a MAC address.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OuiAssignment {
    /// Which IEEE block the match came from.
    pub block: Block,
    /// The assigned prefix as an integer (24, 28 or 36 significant bits).
    pub prefix: u64,
    /// Registered organization name, exactly as IEEE lists it (whitespace
    /// collapsed).
    pub organization: &'static str,
}

impl OuiAssignment {
    /// The prefix in MAC/CIDR notation, e.g. `00:1b:63:00:00:00/24` or
    /// `70:b3:d5:2e:30:00/36`.
    pub fn prefix_cidr(&self) -> String {
        let bits = self.block.prefix_bits();
        let mac = crate::mac::mac_from_u64(self.prefix << (48 - bits)).unwrap_or([0; 6]);
        format!("{}/{bits}", crate::mac::format_mac(&mac))
    }
}

fn read_be(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0u64, |acc, &b| (acc << 8) | u64::from(b))
}

fn name_at(offset: usize) -> Option<&'static str> {
    let len = usize::from(*NAMES.get(offset)?);
    let bytes = NAMES.get(offset + 1..offset + 1 + len)?;
    std::str::from_utf8(bytes).ok()
}

fn search(block: Block, key: u64) -> Option<OuiAssignment> {
    let table = block.table();
    let k = block.key_len();
    let stride = k + 3;
    let (mut lo, mut hi) = (0usize, table.len() / stride);
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let entry = table.get(mid * stride..(mid + 1) * stride)?;
        let probe = read_be(&entry[..k]);
        match probe.cmp(&key) {
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal => {
                let offset = usize::try_from(read_be(&entry[k..])).ok()?;
                return Some(OuiAssignment {
                    block,
                    prefix: key,
                    organization: name_at(offset)?,
                });
            }
        }
    }
    None
}

/// Look a MAC up in the registry, longest prefix first (MA-S, then MA-M, then
/// MA-L): IEEE carves MA-M/MA-S blocks out of MA-L blocks registered to "IEEE
/// Registration Authority", so the most specific assignment wins. `None` when
/// the prefix is unassigned — which includes virtually every locally
/// administered (randomized) MAC.
pub fn lookup(mac: &Mac) -> Option<OuiAssignment> {
    let v = read_be(mac);
    search(Block::MaS, v >> 12)
        .or_else(|| search(Block::MaM, v >> 20))
        .or_else(|| search(Block::MaL, v >> 24))
}

/// Registered organization name for a MAC (see [`lookup`]).
pub fn vendor(mac: &Mac) -> Option<&'static str> {
    lookup(mac).map(|a| a.organization)
}

/// The date (UTC, `YYYY-MM-DD`) the bundled IEEE snapshot was retrieved.
pub fn snapshot_date() -> &'static str {
    SNAPSHOT
        .lines()
        .find_map(|l| l.strip_prefix("retrieved="))
        .unwrap_or("unknown")
}

/// Number of entries per block: `(MA-L, MA-M, MA-S)`.
pub fn entry_counts() -> (usize, usize, usize) {
    (MAL.len() / 6, MAM.len() / 7, MAS.len() / 8)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::mac::parse_mac;

    fn v(s: &str) -> Option<&'static str> {
        vendor(&parse_mac(s).unwrap())
    }

    #[test]
    fn tables_are_well_formed_and_sorted() {
        let (l, m, s) = entry_counts();
        assert!(l > 30_000 && m > 5_000 && s > 5_000, "{l} {m} {s}");
        assert_eq!(MAL.len() % 6, 0);
        assert_eq!(MAM.len() % 7, 0);
        assert_eq!(MAS.len() % 8, 0);
        for block in [Block::MaL, Block::MaM, Block::MaS] {
            let stride = block.key_len() + 3;
            let keys: Vec<u64> = block
                .table()
                .chunks(stride)
                .map(|e| read_be(&e[..block.key_len()]))
                .collect();
            assert!(keys.windows(2).all(|w| w[0] < w[1]), "{block:?} unsorted");
            for e in block.table().chunks(stride) {
                let off = usize::try_from(read_be(&e[block.key_len()..])).unwrap();
                assert!(name_at(off).is_some_and(|n| !n.is_empty()));
            }
        }
        assert_eq!(snapshot_date().len(), 10);
    }

    #[test]
    fn known_vendors() {
        assert_eq!(v("00:1b:63:84:45:e6"), Some("Apple, Inc."));
        assert_eq!(v("00:0c:29:aa:bb:cc"), Some("VMware, Inc."));
        assert_eq!(v("b8:27:eb:01:02:03"), Some("Raspberry Pi Foundation"));
        assert_eq!(v("dc:a6:32:01:02:03"), Some("Raspberry Pi Trading Ltd"));
        assert_eq!(v("fc:fb:fb:01:02:03"), Some("Cisco Systems, Inc"));
        assert_eq!(v("00:00:5e:00:53:01"), Some("ICANN, IANA Department"));
    }

    #[test]
    fn longest_prefix_wins() {
        // a4:58:0f:d… is an MA-M block inside the IEEE RA's a4:58:0f MA-L.
        let a = lookup(&parse_mac("a4:58:0f:d0:00:01").unwrap()).unwrap();
        assert_eq!(a.block, Block::MaM);
        assert_eq!(a.organization, "EYE IO, LLC");
        assert_eq!(a.prefix_cidr(), "a4:58:0f:d0:00:00/28");
        // 8c:1f:64:af:a… is an MA-S assignment.
        let s = lookup(&parse_mac("8c:1f:64:af:a1:23").unwrap()).unwrap();
        assert_eq!(s.block, Block::MaS);
        assert_eq!(s.organization, "DATA ELECTRONIC DEVICES, INC");
        assert_eq!(s.prefix_cidr(), "8c:1f:64:af:a0:00/36");
        let l = lookup(&parse_mac("00:1b:63:84:45:e6").unwrap()).unwrap();
        assert_eq!(
            (l.block, l.prefix_cidr().as_str()),
            (Block::MaL, "00:1b:63:00:00:00/24")
        );
    }

    #[test]
    fn unassigned_and_random() {
        assert_eq!(v("da:a1:19:12:34:56"), None);
        assert_eq!(v("ff:ff:ff:ff:ff:ff"), None);
    }
}
